  "summary": "《艺术的力量》是BBC制作的八集纪录片，每集聚焦一位艺术大师——卡拉瓦乔、伦勃朗、大卫、透纳、梵高、毕加索、罗斯科与波洛克。影片通过戏剧化重现与专家解读，深入剖析艺术家在创作关键节点所经历的精神危机、社会压力与个人痛苦，揭示伟大作品背后的人性挣扎。西蒙·沙玛的解说充满激情与洞见，将艺术史转化为一部关于创造力与苦难的史诗。",
  "review": "不只是讲艺术，更是讲人如何在绝境中创造永恒，看完会对那些名作有截然不同的感受。",
