  "summary": "Netflix日剧，灵感来自宇多田光名曲《First Love》。野口也英与并木晴道在90年代末相遇相爱，却因意外与误会错过二十年。剧集以过去与现在双线交织，讲述两人在各自人生中经历婚姻、事业与失落后重逢的故事。满岛光与佐藤健的表演含蓄深情，北海道雪景与宇多田光的歌声共同营造出浓郁的怀旧氛围。它不仅是一段爱情的追忆，更是对平成时代青春记忆的温柔致敬。",
  "review": "当First Love的旋律响起，所有错过的时光都被原谅——这是写给一代人的情书。",
