  "summary": "改编自同名漫画，讲述热爱烹饪的野本与食量惊人的春日因美食结缘，逐渐发展出超越友谊的亲密关系。剧集以料理为媒介，细腻描绘两位女性在共享餐桌过程中建立的信任与依恋。没有激烈冲突或狗血转折，日常琐碎中流淌着温柔的情感确认。对食物的拍摄充满食欲，每道料理都承载着人物心境变化。作为百合题材中的清新之作，它证明了亲密关系可以如此安静而笃定，无需标签定义。",
  "review": "一碗温热的人间烟火，吃下去整个人都软了下来。",
