  "summary": "落魄律师樱木建二为挽救濒临倒闭的龙山高中，设立以东京大学录取为目标的特别升学班，带领一群被学校和社会放弃的学生冲刺日本最高学府。阿部宽饰演的樱木以毒舌与热血并存的方式激发学生潜能，同时揭露应试教育体制的弊端与学历社会的荒诞。剧集不仅讲升学技巧更讲如何找回自尊与人生的可能性，那些看似功利的应试策略背后是对每个学生个体价值的确认。学生群像鲜活可信，每个人的成长线都有充分铺垫。虽部分应试技巧展示略显夸张，但其热血而不鸡汤的教育理念至今仍有启发意义，是影响了无数亚洲观众的青春励志神作。",
