  "summary": "活了939年的鬼怪金侁为结束永生诅咒寻找能拔出胸口剑的新娘，遇见自称'鬼怪新娘'的高中生池恩倬。两人跨越生死的羁绊牵出前世因果与阴间使者王黎的记忆之谜，三条命运线在宏大世界观中精密交织。金银淑编剧以奇幻外壳包裹极致浪漫与深刻悲伤，孔刘与金高银的演绎让超自然设定落地为真切的人类情感。OST与画面美学达到韩剧新高度，伏笔回收精妙令人叹服。虽中段节奏略有拖沓支线稍显冗余，但其将奇幻爱情拍到极致的完成度使其成为现象级作品，也是韩剧工业化成熟的重要标志。",
