  "summary": "tvN穿越爱情剧。狂热粉丝任素因偶像柳善宰自杀而悲痛欲绝，意外穿越回2008年高中时代，决心阻止善宰走上悲剧之路。两人在青春校园里从陌生到相知，素在拯救善宰的过程中也逐渐治愈了自己的创伤。剧集以双向救赎的情感内核、清新的校园氛围和对偶像产业阴暗面的适度反思脱颖而出，边佑锡与金惠奫的CP感引爆全网，成为2024年最成功的韩剧黑马。",
  "review": "不是粉丝拯救偶像的爽文，而是两个受伤的灵魂在时间里互相接住彼此的温柔故事。",
