  "summary": "三位30代女性安昭熙、韩智妍、姜智久以酒为纽带维系深厚友谊，在酒精催化下袒露职场压力、情感创伤与家庭矛盾中最真实的一面。剧集摒弃了韩剧中常见的爱情主线，专注于女性友谊的真实质地——既有互相扶持的温暖时刻，也有嫉妒、误解与伤害的裂痕。李先彬、韩善花、郑恩地的表演自然松弛毫无表演痕迹，饮酒场景拍出仪式感而非颓废感。终于有韩剧认真拍女人喝酒聊天这件事，轻松之下藏着成年人无法言说的辛酸。虽第二季质量明显下滑，但首季作为女性群像剧的真诚之作仍值得推荐。",
  "review": "终于有韩剧认真拍女人喝酒聊天这件事，轻松之下藏着成年人的辛酸。",
  "pros": [
   "女性群像真实不悬浮，拒绝说教",
   "饮酒场景拍出仪式感而非颓废感"
  ],
  "cons": [
   "第二季质量明显下滑，首季更佳"
  ],
